import { test, expect } from '@playwright/test';

test.describe('Notification Click Navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/notifications');
  });

  test('should navigate to related content when clicking a notification', async ({ page }) => {
    // Verify notification list is visible
    const notificationList = page.getByRole('region', { name: /notifications/i });
    await expect(notificationList).toBeVisible();

    // Verify notification item has correct role and label
    const notificationItem = page.getByRole('button', { name: /new post/i });
    await expect(notificationItem).toBeVisible();

    // Verify notification content is visible
    const notificationContent = page.getByText(/new post/i);
    await expect(notificationContent).toBeVisible();

    // Verify navigation link is present and visible
    const navigationLink = page.getByRole('link', { name: /read post/i });
    await expect(navigationLink).toBeVisible();

    // Click notification item
    await notificationItem.click();

    // Verify navigation link is now active
    await expect(navigationLink).toBeActive();

    // Verify navigation URL is correct
    const navigationUrl = page.url();
    expect(navigationUrl).toContain('/posts/123');

    // Verify related content is visible
    const relatedContent = page.getByRole('region', { name: /related content/i });
    await expect(relatedContent).toBeVisible();

    // Verify content title is present
    const contentTitle = page.getByText(/related content/i);
    await expect(contentTitle).toBeVisible();

    // Verify content body is visible
    const contentBody = page.getByText(/this is related content/i);
    await expect(contentBody).toBeVisible();

    // Verify back button is present
    const backButton = page.getByRole('button', { name: /back to notifications/i });
    await expect(backButton).toBeVisible();
  });

  test('should handle edge case: notification item is disabled and should not navigate', async ({ page }) => {
    // Verify notification list is visible
    const notificationList = page.getByRole('region', { name: /notifications/i });
    await expect(notificationList).toBeVisible();

    // Verify notification item is disabled
    const notificationItem = page.getByRole('button', { name: /new post/i });
    await expect(notificationItem).toBeDisabled();

    // Verify notification content is visible
    const notificationContent = page.getByText(/new post/i);
    await expect(notificationContent).toBeVisible();

    // Verify navigation link is not visible
    const navigationLink = page.getByRole('link', { name: /read post/i });
    await expect(navigationLink).not.toBeVisible();

    // Verify notification item is still visible
    await expect(notificationItem).toBeVisible();

    // Verify notification item is still disabled
    await expect(notificationItem).toBeDisabled();

    // Verify no navigation occurs
    await expect(page).toHaveURL(/\/notifications/);
  });
});
